    public Object parseTrade(Object trade, Map<String, Object> market)
    {
        //
        // fetchMyTrades
        //
        //     {
        //         "type": "BTC Sell order executed",
        //         "typeI": 6,
        //         "crypto": 5000,
        //         "amount": 35.4,
        //         "rate": 709800,
        //         "date": "2020-05-22T15:05:34.000Z",
        //         "unit": "INR",
        //         "factor": 100000000,
        //         "fee": 0.09,
        //         "delh_btc": -5000,
        //         "delh_inr": 0,
        //         "del_btc": 0,
        //         "del_inr": 35.4,
        //         "id": "2938823"
        //     }
        //
        // fetchTrades
        //
        //     {
        //         "tradeId":"1909151",
        //         "price":"61904.6300",
        //         "quote_volume":1618.05,
        //         "base_volume":0.02607254,
        //         "timestamp":1634548602000,
        //         "type":"buy"
        //     }
        //
        market = (Map<String, Object>) (this.safeMarket(null, market));
        String orderId = this.safeString2(trade, "id", "tradeId");
        Long timestamp = this.parse8601(this.safeString(trade, "date"));
        timestamp = (Long) this.safeInteger(trade, "timestamp", timestamp);
        String priceString = this.safeString2(trade, "rate", "price");
        String amountString = this.safeString(trade, "amount");
        String side = this.safeStringLower(trade, "type");
        if (!java.util.Objects.equals(side, null))
        {
            if (((String)side).indexOf("buy") >= 0)
            {
                side = "buy";
            } else if (((String)side).indexOf("sell") >= 0)
            {
                side = "sell";
            }
        }
        String factor = this.safeString(trade, "factor");
        String costString = null;
        if (!java.util.Objects.equals(factor, null))
        {
            amountString = Precise.stringDiv(amountString, factor);
        } else
        {
            amountString = this.safeString(trade, "base_volume");
            costString = this.safeString(trade, "quote_volume");
        }
        String symbol = (String) ((Map<String, Object>)market).get("symbol");
        Map<String, Object> fee = null;
        String feeCostString = this.safeString(trade, "fee");
        if (!java.util.Objects.equals(feeCostString, null))
        {
            String feeCurrencyCode = (String) ((Map<String, Object>)market).get("quote");
            final String finalFeeCostString = feeCostString;
            fee = new HashMap<String, Object>() {{
                put( "cost", finalFeeCostString );
                put( "currency", feeCurrencyCode );
            }};
        }
        final Long finalTimestamp = timestamp;
        final String finalSide = side;
        final String finalAmountString = amountString;
        final String finalCostString = costString;
        final Map<String, Object> finalFee = fee;
        return this.safeTrade((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "info", trade );
            put( "timestamp", finalTimestamp );
            put( "datetime", Bitbns.this.iso8601(finalTimestamp) );
            put( "symbol", symbol );
            put( "id", orderId );
            put( "order", orderId );
            put( "type", null );
            put( "side", finalSide );
            put( "takerOrMaker", null );
            put( "price", priceString );
            put( "amount", finalAmountString );
            put( "cost", finalCostString );
            put( "fee", finalFee );
        }}), market);
    }
    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        return this.parseTrade(trade, Helpers.getArgMap(optionalArgs, 0, null));
    }

