    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        // fetchDeposits
        //
        //     {
        //         "type":"USDT deposited",
        //         "typeI":1,
        //         "amount":100,
        //         "date":"2021-04-24T14:56:04.000Z",
        //         "unit":"USDT",
        //         "factor":100,
        //         "fee":0,
        //         "delh_btc":0,
        //         "delh_inr":0,
        //         "rate":0,
        //         "del_btc":10000,
        //         "del_inr":0
        //     }
        //
        // fetchWithdrawals
        //
        //     ...
        //
        String currencyId = this.safeString(transaction, "unit");
        String code = this.safeCurrencyCode(currencyId, currency);
        Long timestamp = this.parse8601(this.safeString2(transaction, "date", "timestamp"));
        String type = this.safeString(transaction, "type");
        String expTime = this.safeString(transaction, "expTime", "");
        String status = null;
        if (!java.util.Objects.equals(type, null))
        {
            if (((String)type).indexOf("deposit") >= 0)
            {
                type = "deposit";
                status = "ok";
            } else if (((String)type).indexOf("withdraw") >= 0 || ((String)expTime).indexOf("withdraw") >= 0)
            {
                type = "withdrawal";
            }
        }
        // const status = this.parseTransactionStatusByType (this.safeString (transaction, 'status'), type);
        Double amount = this.safeNumber(transaction, "amount");
        Double feeCost = this.safeNumber(transaction, "fee");
        Map<String, Object> fee = null;
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Double finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", finalFeeCost );
            }};
        }
        final String finalType = type;
        final String finalStatus = status;
        final Map<String, Object> finalFee = fee;
        return new HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", null );
            put( "txid", null );
            put( "timestamp", timestamp );
            put( "datetime", Bitbns.this.iso8601(timestamp) );
            put( "network", null );
            put( "address", null );
            put( "addressTo", null );
            put( "addressFrom", null );
            put( "tag", null );
            put( "tagTo", null );
            put( "tagFrom", null );
            put( "type", finalType );
            put( "amount", amount );
            put( "currency", code );
            put( "status", finalStatus );
            put( "updated", null );
            put( "comment", null );
            put( "internal", null );
            put( "fee", finalFee );
        }};
    }
    public Object parseTransaction(Map<String, Object> transaction, Object... optionalArgs)
    {
        return this.parseTransaction(transaction, Helpers.getArgMap(optionalArgs, 0, null));
    }

